// Generates the step wiki under docs/ from the JSDoc docstrings on every step
// definition. Run via `npm run wiki`.
//
//   docs/index.md          overview: one row per @domain, with step counts + links
//   docs/<domain-slug>.md   one page per domain, a section per step
//
// Generated files carry a marker on line 1 so re-runs can prune pages for domains
// that no longer exist without ever touching hand-written docs.

import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseSteps } from "./lib/parse-steps.mjs";

const ROOT = process.cwd();
const DOCS_DIR = join(ROOT, "docs");
const MARKER = "<!-- GENERATED by `npm run wiki` — do not edit by hand -->";

function slugify(domain) {
  return (
    domain
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "") || "uncategorized"
  );
}

function groupByDomain(steps) {
  const groups = new Map();
  for (const step of steps) {
    const domain = step.domain || "uncategorized";
    if (!groups.has(domain)) groups.set(domain, []);
    groups.get(domain).push(step);
  }
  return groups;
}

function renderIndex(groups) {
  const rows = [...groups.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(
      ([domain, steps]) =>
        `| ${domain} | ${steps.length} | [${slugify(domain)}.md](./${slugify(domain)}.md) |`,
    )
    .join("\n");
  const total = [...groups.values()].reduce((n, s) => n + s.length, 0);
  const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
  return `${MARKER}

# Step Wiki

Auto-generated catalogue of every BDD step definition, grouped by \`@domain\`.
Regenerate with \`npm run wiki\`. Reuse these before writing new steps.

**${plural(total, "step")} across ${plural(groups.size, "domain")}.**

| Domain | Steps | Page |
| --- | --- | --- |
${rows}
`;
}

function renderDomain(domain, steps) {
  const sections = steps
    .sort((a, b) => a.pattern.localeCompare(b.pattern))
    .map((step) => {
      const uses = step.uses.length ? step.uses.join(", ") : "none";
      return `### \`${step.keyword}\` ${step.pattern}

${step.description || "_no description_"}

- **Prereq:** ${step.prereq || "none"}
- **Uses:** ${uses}
- **Source:** \`${step.file}:${step.line}\`
`;
    })
    .join("\n");
  return `${MARKER}

# ${domain}

[← back to index](./index.md)

${sections}`;
}

function pruneStaleDocs(keep) {
  let files;
  try {
    files = readdirSync(DOCS_DIR);
  } catch {
    return;
  }
  for (const name of files) {
    if (!name.endsWith(".md") || keep.has(name)) continue;
    const full = join(DOCS_DIR, name);
    const firstLine = readFileSync(full, "utf8").split("\n", 1)[0];
    if (firstLine.includes(MARKER)) rmSync(full);
  }
}

function main() {
  const steps = parseSteps({ root: ROOT });
  const groups = groupByDomain(steps);
  mkdirSync(DOCS_DIR, { recursive: true });

  const written = new Set(["index.md"]);
  writeFileSync(join(DOCS_DIR, "index.md"), renderIndex(groups));
  for (const [domain, domainSteps] of groups) {
    const name = `${slugify(domain)}.md`;
    written.add(name);
    writeFileSync(join(DOCS_DIR, name), renderDomain(domain, domainSteps));
  }
  pruneStaleDocs(written);

  console.log(`wiki: ${steps.length} steps → ${groups.size} domain page(s) in docs/`);
}

main();
